    // Compute base address for this batch
    // ------------------------------------------------------------------
    mul.wide.u32 %rd3, %r3, %r1;         // batch * N (element count)
    mul.wide.u32 %rd3, %rd3, 2;          // *2 bytes per fp16
    add.u64 %rd4, %rd1, %rd3;            // input base pointer for this batch
    add.u64 %rd5, %rd2, %rd3;            // output base pointer for this batch

    // ------------------------------------------------------------------
    // First pass: compute mean
    // ------------------------------------------------------------------
    mov.f32 %f0, 0.0;                    // local sum
    mov.u32 %r5, %r2;                    // i = threadIdx

mean_loop:
    setp.ge.u32 %p0, %r5, %r1;
    @%p0 bra mean_loop_end;

    mul.wide.u32 %rd6, %r5, 2;           // byte offset = i*2
    add.u64 %rd6, %rd4, %rd6;            // address of element
    ld.global.f16 %h0, [%rd6];
    cvt.f32.f16 %f1, %h0;
    add.f32 %f0, %f0, %f1;               // sum += value

    add.u32 %r5, %r5, %r4;               // i += stride
    bra mean_loop;
mean_loop_end:

    // Reduce sum within block (shared memory reduction)
    .shared .align 4 .b32 sdata[256];
    st.shared.u32 [sdata+%r2*4], %f0;
    bar.sync 0;

    // Tree reduction (assume blockDim.x is power‑of‑two ≤256)
    .reg .u32 %s;
    mov.u32 %s, 128;
reduce_sum:
    setp.ge.u32 %p1, %r2, %s;
    @%p1 bra skip_sum_reduce;
    ld.shared.u32 %r6, [sdata+%r2*4];
    ld.shared.u32 %r7, [sdata+(%r2+%s)*4];
    add.u32 %r6, %r6, %r7;
    st.shared.u32 [sdata+%r2*4], %r6;
skip_sum_reduce:
