    ld.shared.u32 %r6, [sdata];
    mov.b32 %f2, %r6;                    // sum as float bits
    cvt.f32.u32 %f2, %f2;                // (no conversion needed, just reinterpret)
    cvt.f32.u32 %f3, %r1;                // N as float
    div.full.f32 %f3, %f2, %f3;          // mean = sum / N

    // ------------------------------------------------------------------
    // Second pass: compute variance
    // ------------------------------------------------------------------
    mov.f32 %f4, 0.0;                    // variance accumulator
    mov.u32 %r5, %r2;                    // i = threadIdx

var_loop:
    setp.ge.u32 %p0, %r5, %r1;
    @%p0 bra var_loop_end;

