    add.u64 %rd6, %rd4, %rd6;
    ld.global.f16 %h0, [%rd6];
    cvt.f32.f16 %f1, %h0;
    sub.f32 %f1, %f1, %f3;               // (x - mean)
    mul.f32 %f1, %f1, %f1;               // (x-mean)^2
    add.f32 %f4, %f4, %f1;               // accumulate

    add.u32 %r5, %r5, %r4;
    bra var_loop;
var_loop_end:

    st.shared.u32 [sdata+%r2*4], %f4;
    bar.sync 0;

