    mov.u32 %s, 128;
reduce_var:
    setp.ge.u32 %p1, %r2, %s;
    @%p1 bra skip_var_reduce;
    ld.shared.u32 %r6, [sdata+%r2*4];
    ld.shared.u32 %r7, [sdata+(%r2+%s)*4];
    add.u32 %r6, %r6, %r7;
    st.shared.u32 [sdata+%r2*4], %r6;
skip_var_reduce:
    bar.sync 0;
    shr.u32 %s, %s, 1;
    setp.ne.u32 %p1, %s, 0;
    @%p1 bra reduce_var;

    ld.shared.u32 %r6, [sdata];
    mov.b32 %f4, %r6;                    // variance sum as bits
    cvt.f32.u32 %f4, %f4;
    cvt.f32.u32 %f5, %r1;                // N as float
    div.full.f32 %f5, %f4, %f5;          // variance = var_sum / N

