    // Third pass: write normalized output
    // ------------------------------------------------------------------
    mov.u32 %r5, %r2;                    // i = threadIdx

write_loop:
    setp.ge.u32 %p0, %r5, %r1;
    @%p0 bra write_loop_end;

    mul.wide.u32 %rd6, %r5, 2;
    add.u64 %rd6, %rd4, %rd6;            // input address
    ld.global.f16 %h0, [%rd6];
    cvt.f32.f16 %f1, %h0;
    sub.f32 %f1, %f1, %f3;               // x - mean
    mul.f32 %f1, %f1, %f5;               // * inv_std
    cvt.rn.f16.f32 %h1, %f1;             // back to fp16 (round‑to‑nearest)

    // store result
    mul.wide.u32 %rd6, %r5, 2;
    add.u64 %rd6, %rd5, %rd6;            // output address
    st.global.f16 [%rd6], %h1;

    add.u32 %r5, %r5, %r4;
    bra write_loop;
write_loop_end:

